    await settle();
    expect(conversationRows(w)).toHaveLength(18);
  });

  it('documents Shift+U as explicit mark-unread and guards modifiers/IME/text fields', async () => {
    gmail();
    const w = mountApp();
    await settle();
    window.dispatchEvent(keydown({ key: 'U', shiftKey: true }));
